const app=document.getElementById('app'),toast=document.getElementById('toast');
const uiObserver=new MutationObserver(()=>{if(state.lang==='ar')requestAnimationFrame(translateUI)});uiObserver.observe(app,{childList:true,subtree:true});
const isAdminPortal=()=>location.pathname==='/admin'||location.pathname==='/admin/'||location.pathname==='/admin.html';
const state={me:null,view:'home',exam:null,questions:[],attemptId:null,timer:null,answers:{},marked:{},submitting:false,expired:false,mobileWarningShown:false,adminTab:'overview',editingExam:null,editingQuestion:null,lang:localStorage.getItem('exam_lang')||'en',theme:localStorage.getItem('exam_theme')||'dark'};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
const translations={
  'Home':'الرئيسية','Exams':'الامتحانات','Results':'النتائج','Student Login':'دخول الطالب','Get started':'ابدأ الآن','Dashboard':'لوحة التحكم','Logout':'تسجيل الخروج',
  'Finance learning · assessment · performance':'التعلم المالي · التقييم · الأداء','Assess what you know.':'قيّم ما تعرفه.','Measure what you can do.':'قِس ما يمكنك القيام به.',
  'A focused assessment workspace for finance learners — built around real exams, timed performance and clear results.':'منصة تقييم متخصصة لطلاب ومتخصصي المالية — مبنية حول الامتحانات الفعلية والأداء المحدد بالوقت ونتائج واضحة.',
  'NEW STUDENT':'طالب جديد','ALREADY REGISTERED':'لديك حساب بالفعل','Create your student account and receive your Student ID.':'أنشئ حساب الطالب واحصل على رقم الطالب الخاص بك.','Continue to your dashboard and active assessments.':'انتقل إلى لوحة التحكم والامتحانات المتاحة.',
  'Student access':'دخول الطالب','Welcome back.':'مرحباً بعودتك.','Use your Student ID or email and password.':'استخدم رقم الطالب أو البريد الإلكتروني وكلمة المرور.','Student ID / Email':'رقم الطالب / البريد الإلكتروني','Password':'كلمة المرور','Login':'دخول','No account?':'ليس لديك حساب؟','Register here':'سجّل هنا',
  'New student':'طالب جديد','Create your account.':'أنشئ حسابك.','Your Student ID is generated automatically. You will see it immediately after registration.':'يتم إنشاء رقم الطالب تلقائياً وسيظهر لك مباشرة بعد التسجيل.','Full name':'الاسم بالكامل','Email':'البريد الإلكتروني','Register & Get Student ID':'التسجيل والحصول على رقم الطالب','Already registered?':'لديك حساب بالفعل؟',
  'Student dashboard':'لوحة الطالب','Performance':'الأداء','My results':'نتائجي','No active exams are available right now.':'لا توجد امتحانات متاحة حالياً.','Your completed exams will appear here.':'ستظهر امتحاناتك المكتملة هنا.','Start Exam ↗':'بدء الامتحان ↗','Passed':'ناجح','Not passed':'لم ينجح',
  'Active assessment':'الامتحان الحالي','Assessment resources':'موارد الامتحان','Files for this exam':'ملفات هذا الامتحان','Download the files you need before answering the questions.':'حمّل الملفات التي تحتاجها قبل الإجابة عن الأسئلة.','Download':'تحميل','Submit Exam':'تسليم الامتحان','Leave':'مغادرة',
  'Assessment result':'نتيجة الامتحان','Back to Dashboard':'العودة إلى لوحة التحكم','Retake Exam':'إعادة الامتحان','Completed':'مكتمل','Pass mark':'درجة النجاح','Points earned':'النقاط المحصلة','Questions answered':'الأسئلة المُجاب عنها','Excellent performance.':'أداء ممتاز.','You passed this assessment.':'لقد اجتزت هذا الامتحان بنجاح.','Keep practicing and try again.':'استمر في التدريب وحاول مرة أخرى.','You did not reach the passing mark this time.':'لم تصل إلى درجة النجاح هذه المرة.','Overall score':'النتيجة النهائية','Assessment complete':'اكتمل الامتحان','Administration':'الإدارة','Control center.':'مركز التحكم.','Authorized administrators only.':'للمسؤولين المصرح لهم فقط.','Admin Login':'دخول المسؤول','Student?':'طالب؟','Student login':'دخول الطالب'
};
function translateUI(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';if(state.lang!=='ar')return;const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const v=n.nodeValue.trim();if(translations[v])n.nodeValue=n.nodeValue.replace(v,translations[v]);}}

async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.error||'Request failed');return d}
function fmtDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString():''}
function layout(content,opts={}){const adminPortal=isAdminPortal();const ar=state.lang==='ar';const nav=adminPortal?`<nav class="site-nav"><button onclick="adminTab('overview');closeMobileMenu()">${ar?'الرئيسية':'Home'}</button><button onclick="adminTab('exams');closeMobileMenu()">${ar?'الامتحانات':'Exams'}</button><button onclick="adminTab('results');closeMobileMenu()">${ar?'النتائج':'Results'}</button><a href="https://case-lab.pages.dev/" target="_blank" rel="noopener noreferrer" onclick="closeMobileMenu()">case-lab</a></nav>`:`<nav class="site-nav"><button onclick="go('home');closeMobileMenu()">${ar?'الرئيسية':'Home'}</button><button onclick="go('dashboard');closeMobileMenu()">${ar?'الامتحانات':'Exams'}</button><button onclick="go('results');closeMobileMenu()">${ar?'النتائج':'Results'}</button><a href="https://case-lab.pages.dev/" target="_blank" rel="noopener noreferrer" onclick="closeMobileMenu()">case-lab</a></nav>`;const auth=adminPortal?(state.me?.admin?`<button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:''):state.me?.user?`<button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة التحكم':'Dashboard'}</button><button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:`<button class="btn ghost" onclick="go('login')">${ar?'دخول الطالب':'Student Login'}</button><button class="btn orange" onclick="go('register')">${ar?'ابدأ الآن':'Get started'}</button>`;return `<div class="shell"><header class="topbar"><div class="brand"><img class="brand-logo" src="/ae-logo.png" alt="AE"><div class="brand-name">Ahmed Elsheshtawy<small>Ahmed Finance · EXAM PLATFORM</small></div></div><button class="mobile-menu-btn" onclick="toggleMobileMenu()" aria-label="Menu">☰</button>${nav}<div class="top-actions"><button class="circle-btn" onclick="toggleLang();closeMobileMenu()" aria-label="Language">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn" onclick="toggleTheme();closeMobileMenu()" aria-label="Theme">${state.theme==='dark'?'☼':'✦'}</button>${auth}<a class="connect-btn" href="https://ahmed-portfolio.ahmedelsheshtawyofficial.workers.dev/#contact" target="_blank" rel="noopener noreferrer">${ar?'تواصل معي ↗':"Let's Connect ↗"}</a></div></header>${content}<footer class="footer">Numbers tell a story. I analyze it. · Ahmed Elsheshtawy</footer></div>`}
function toggleMobileMenu(){document.querySelector('.topbar')?.classList.toggle('mobile-menu-open')}
function closeMobileMenu(){document.querySelector('.topbar')?.classList.remove('mobile-menu-open')}
async function boot(){applyTheme();try{state.me=await api('/api/auth/me')}catch{}const adminPortal=isAdminPortal();if(adminPortal)state.view=state.me?.admin?'admin':'admin-login';else state.view=state.me?.user?'dashboard':'home';render()}
function render(){const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.me?.user&&state.view==='home')state.view='dashboard';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
function renderHome(){app.innerHTML=layout(`<main class="home-page"><section class="home-hero"><div class="home-copy"><div class="home-kicker"><span class="home-dot"></span> Finance learning · assessment · performance</div><h1>Assess what you know.<br><span>Measure what you can do.</span></h1><p>A focused assessment workspace for finance learners — built around real exams, timed performance and clear results.</p></div><div class="home-entry"><button class="entry-card entry-primary" onclick="go('register')"><span class="entry-number">01</span><span class="entry-content"><small>NEW STUDENT</small><strong>Get started</strong><em>Create your student account and receive your Student ID.</em></span><span class="entry-arrow">↗</span></button><button class="entry-card" onclick="go('login')"><span class="entry-number">02</span><span class="entry-content"><small>ALREADY REGISTERED</small><strong>Student Login</strong><em>Continue to your dashboard and active assessments.</em></span><span class="entry-arrow">↗</span></button></div></section></main>`)}
function renderAdminLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Administration</div><h1>Control center.</h1><p class="muted">Authorized administrators only.</p><form class="form" onsubmit="adminLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Admin Login</button></form><p class="small-text muted">Student? <span class="link" onclick="go('login')">Student login</span></p></div></div></main>`)}
async function adminLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');state.view='admin';render()}catch(x){showToast(x.message)}}
function renderLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Student access</div><h1>Welcome back.</h1><p class="muted">Use your Student ID or email and password.</p><form class="form" onsubmit="studentLogin(event)"><div class="field"><label>Student ID / Email</label><input name="identifier" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Login</button></form><p class="small-text muted">No account? <span class="link" onclick="go('register')">Register here</span></p></div></div></main>`)}
function renderRegister(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">New student</div><h1>Create your account.</h1><p class="muted">Your Student ID is generated automatically. You will see it immediately after registration.</p><form class="form" onsubmit="studentRegister(event)"><div class="field"><label>Full name</label><input name="fullName" required maxlength="120"></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" maxlength="128" required></div><button class="btn orange">Register & Get Student ID</button></form><p class="small-text muted">Already registered? <span class="link" onclick="go('login')">Login</span></p></div></div></main>`)}
async function studentLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');showToast('Login successful');go('dashboard')}catch(x){showToast(x.message)}}
async function studentRegister(e){e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');app.innerHTML=layout(`<main class="page"><div class="center"><div class="card result-box"><div class="eyebrow">Registration complete</div><h2>Your Student ID</h2><div class="score">${esc(d.studentId)}</div><p class="muted">Save this ID. You can use it or your email to log in.</p><button class="btn orange" onclick="go('dashboard')">Continue to Dashboard</button></div></div></main>`)}catch(x){showToast(x.message)}}
async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;state.view=(isAdminPortal())?'admin-login':'home';render()}
async function renderDashboard(){let exams=[],results=[];try{[exams,results]=await Promise.all([api('/api/exams'),api('/api/results')])}catch(x){showToast(x.message)}app.innerHTML=layout(`<main class="page"><div class="dashboard-head"><div><div class="eyebrow">Student dashboard</div><h1>${esc(state.me.user.fullName)}</h1><p class="muted">Student ID · <b>${esc(state.me.user.studentId)}</b></p></div></div><section class="grid grid-3">${exams.length?exams.map(examCard).join(''):`<div class="card empty">No active exams are available right now.</div>`}</section><div class="section-head"><div><div class="eyebrow">Performance</div><h2>My results</h2></div></div><div class="card">${results.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th></tr></thead><tbody>${results.map(r=>`<tr><td>${esc(r.title)}</td><td>${r.score} / ${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Your completed exams will appear here.</div>`}</div></main>`)}
function examCard(e){const files=Array.isArray(e.attachments)?e.attachments.length:0;return `<article class="card exam-card"><span class="pill ${e.status==='active'?'active':''}">${e.status}</span><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description||'Finance assessment')}</p><div class="exam-meta"><span>${e.question_count} questions</span><span>·</span><span>${e.duration_minutes} min</span><span>·</span><span>Pass ${e.passing_percentage}%</span>${files?`<span>·</span><span>${files} file${files===1?'':'s'}</span>`:''}</div><button class="btn orange" onclick="startExam(${e.id})">Start Exam ↗</button></article>`}
async function startExam(id){
  try{
    clearInterval(state.timer);
    state.submitting=false;
    state.expired=false;
    state.answers={};
    state.questions=[];
    const d=await api(`/api/exams/${id}/start`);
    if(!d?.exam) throw new Error('Exam data could not be loaded');
    if(!Array.isArray(d.questions)) throw new Error('Exam questions could not be loaded');
    if(!d.attemptId) throw new Error('Exam attempt could not be created');
    state.exam=d.exam;
    state.questions=d.questions;
    state.attemptId=d.attemptId;
    state.startedAt=d.startedAt;
    state.view='exam';
    renderExam();
    startTimer();
  }catch(x){
    console.error('START EXAM ERROR:',x);
    if(x.message==='لا يمكن دخول الامتحان مرة أخرى لأنك اجتزت هذا الامتحان بالفعل.')showToast('لا يمكن دخول الامتحان مرة أخرى — لقد اجتزت هذا الامتحان بالفعل.');
    else showToast(x.message||'Unable to start exam');
  }
}
function renderExam(){
 const ar=state.lang==='ar',total=state.questions.length,answered=Object.keys(state.answers).length,markedCount=Object.keys(state.marked).filter(id=>state.marked[id]).length,idx=Math.max(0,Math.min(Number(state.currentQuestionIndex)||0,total-1)),q=state.questions[idx];
 const L=ar?{k:'الامتحان الحالي',a:'تمت الإجابة',of:'من',submit:'تسليم الامتحان',leave:'مغادرة الامتحان',res:'ملفات هذا السؤال',dl:'تنزيل الملف',file:'ملف',q:'السؤال',pt:'نقطة',next:'السؤال التالي',prev:'السؤال السابق',mark:'تحديد للمراجعة',unmark:'إلغاء التحديد',review:'مراجعة الأسئلة',marked:'أسئلة محددة للمراجعة',finish:'مراجعة وتسليم'}:{k:'Active assessment',a:'Answered',of:'of',submit:'Submit exam',leave:'Leave exam',res:'Files for this question',dl:'Download file',file:'File',q:'Question',pt:'point',next:'Next question',prev:'Previous question',mark:'Mark for review',unmark:'Unmark',review:'Question review',marked:'Marked for review',finish:'Review & submit'};
 const selected=q?state.answers[q.id]:null,isMarked=q?!!state.marked[q.id]:false,files=Array.isArray(q?.attachments)?q.attachments:[],pct=total?Math.round(answered/total*100):0;
 const filesHtml=files.length?`<div class="question-files"><div class="question-files-head"><div><div class="eyebrow">${L.res}</div><div class="small-text muted">${files.length} ${L.file}${files.length===1?'':'s'}</div></div></div><div class="exam-file-list">${files.map((f,j)=>`<div class="exam-file"><div class="file-icon">↓</div><div class="file-info"><b>${esc(f.name)}</b><span class="small-text muted">${L.file} ${j+1}</span></div><div class="file-actions"><a class="btn small ghost" href="${esc(f.url)}" download>${L.dl} ↓</a></div></div>`).join('')}</div></div>`:'';
 const qhtml=q?`<section class="question exam-question is-current"><div class="question-head"><div class="question-number">${String(idx+1).padStart(2,'0')}</div><div class="question-head-copy"><div class="small-text muted">${L.q} ${idx+1} · ${q.points} ${L.pt}${q.points==1?'':'s'}</div><div class="question-title">${esc(q.question_text)}</div></div><button type="button" class="question-mark-btn ${isMarked?'is-marked':''}" onclick="toggleQuestionMark(${q.id})">${isMarked?'⚑':'⚐'} <span>${isMarked?L.unmark:L.mark}</span></button></div>${filesHtml}<div class="options">${['A','B','C','D'].map(k=>`<label class="option ${selected===k?'is-selected':''}"><input type="radio" name="q${q.id}" value="${k}" ${selected===k?'checked':''} onchange="setExamAnswer(${q.id},'${k}')"><span class="option-letter">${k}</span><span>${esc(q['option_'+k.toLowerCase()])}</span></label>`).join('')}</div></section>`:'';
 const reviewItems=state.questions.map((rq,ri)=>{const a=!!state.answers[rq.id],m=!!state.marked[rq.id];if(!m&&!(!a))return '';return `<button type="button" class="review-item ${m?'is-marked':''} ${!a?'is-unanswered':''}" onclick="jumpToExamQuestion(${ri})"><span>${String(ri+1).padStart(2,'0')}</span><b>${esc(rq.question_text.slice(0,80))}</b><em>${!a?(ar?'بدون إجابة':'Unanswered'):(m?(ar?'محدد':'Marked'):(ar?'تمت الإجابة':'Answered'))}</em></button>`}).join('');
 app.innerHTML=layout(`<main class="page exam-page"><div class="exam-shell"><div class="exam-top exam-toolbar"><div class="exam-title-wrap"><div class="eyebrow">${L.k}</div><h1>${esc(state.exam.title)}</h1><div class="exam-progress"><span id="exam-progress-text">${answered} ${L.of} ${total} ${L.a}</span><span class="progress-track"><i id="exam-progress-bar" style="width:${pct}%"></i></span></div></div><div class="exam-timer-box"><span class="small-text muted">${ar?'الوقت المتبقي':'Time remaining'}</span><div class="timer" id="timer">--:--</div></div></div><div class="exam-status-row"><span class="pill">${idx+1} ${L.of} ${total}</span><span class="pill">${markedCount} ${L.marked}</span></div><form id="exam-form" onsubmit="submitExam(event)"><div id="question-stage">${qhtml}</div><div class="question-navigation"><button id="prev-question-btn" type="button" class="btn ghost" onclick="previousExamQuestion()">${L.prev}</button><span id="question-counter" class="small-text muted">${idx+1} ${L.of} ${total}</span><button id="next-question-btn" type="button" class="btn orange" onclick="nextExamQuestion()">${idx===total-1?L.finish:L.next} ${idx===total-1?'✓':'↗'}</button></div><section class="review-panel card"><div class="review-panel-head"><div><div class="eyebrow">${L.review}</div><h3>${L.marked}</h3></div><span class="pill">${markedCount}</span></div><div class="review-items">${reviewItems||`<div class="small-text muted">${ar?'لا توجد أسئلة محددة حاليًا.':'No questions are marked yet.'}</div>`}</div></section><div class="submit-panel card"><div><strong>${L.submit}</strong><span class="small-text muted"> · ${answered}/${total} ${L.a}</span></div><div class="actions"><button type="button" class="btn ghost" onclick="leaveExam()">${L.leave}</button><button id="submit-exam-btn" class="btn orange" type="submit" ${answered===total?'':'disabled'}>${L.finish} ↗</button></div></div></form></div></main>`); updateQuestionNavigation();if(ar)translateUI();
}
function setExamAnswer(questionId,answer){state.answers[questionId]=answer;document.querySelectorAll(`input[name="q${questionId}"]`).forEach(input=>{input.checked=input.value===answer;input.closest('.option')?.classList.toggle('is-selected',input.value===answer)});updateExamProgress()}
function toggleQuestionMark(questionId){state.marked[questionId]=!state.marked[questionId];renderExam()}
function jumpToExamQuestion(index){state.currentQuestionIndex=Math.max(0,Math.min(Number(index)||0,state.questions.length-1));renderExam();window.scrollTo({top:0,behavior:'smooth'})}
function updateExamProgress(){const total=state.questions.length,answered=Object.keys(state.answers).length,pct=total?Math.round(answered/total*100):0,text=document.getElementById('exam-progress-text'),bar=document.getElementById('exam-progress-bar');if(text)text.textContent=`${answered} ${state.lang==='ar'?'من':'of'} ${total} ${state.lang==='ar'?'تمت الإجابة':'answered'}`;if(bar)bar.style.width=`${pct}%`;const submit=document.getElementById('submit-exam-btn');if(submit&&!state.submitting)submit.disabled=answered!==total}
function updateQuestionNavigation(){const total=state.questions.length;if(!total)return;const idx=Math.max(0,Math.min(Number(state.currentQuestionIndex)||0,total-1));state.currentQuestionIndex=idx;const counter=document.getElementById('question-counter'),prev=document.getElementById('prev-question-btn'),next=document.getElementById('next-question-btn');if(counter)counter.textContent=`${idx+1} ${state.lang==='ar'?'من':'of'} ${total}`;if(prev)prev.disabled=idx===0;if(next)next.textContent=idx===total-1?(state.lang==='ar'?'مراجعة وتسليم ✓':'Review & submit ✓'):(state.lang==='ar'?'السؤال التالي ↗':'Next question ↗')}
function nextExamQuestion(){const idx=Number(state.currentQuestionIndex)||0;if(idx<state.questions.length-1){state.currentQuestionIndex=idx+1;renderExam();window.scrollTo({top:0,behavior:'smooth'})}else{const unanswered=state.questions.length-Object.keys(state.answers).length;if(unanswered){showToast(state.lang==='ar'?`ما زال هناك ${unanswered} سؤال بدون إجابة. يمكنك مراجعتها من قائمة المراجعة.`:`${unanswered} question(s) are unanswered. Review them before submitting.`);const first=state.questions.findIndex(q=>!state.answers[q.id]);if(first>=0){state.currentQuestionIndex=first;renderExam()}}else document.getElementById('submit-exam-btn')?.focus()}}
function previousExamQuestion(){const idx=Number(state.currentQuestionIndex)||0;if(idx>0){state.currentQuestionIndex=idx-1;renderExam();window.scrollTo({top:0,behavior:'smooth'})}}
function leaveExam(){const ar=state.lang==='ar',unanswered=state.questions.length-Object.keys(state.answers).length;if(unanswered){showToast(ar?'لا يمكنك مغادرة الامتحان قبل إكمال الإجابة على جميع الأسئلة.':'You cannot leave the exam until all questions are answered.');return}if(confirm(ar?'هل تريد مغادرة الامتحان؟':'Leave the exam?'))go('dashboard')}
function maybeShowMobileWarning(){if(state.mobileWarningShown||!state.exam?.mobile_warning)return;const isMobile=window.matchMedia('(max-width: 800px)').matches||/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);if(!isMobile)return;state.mobileWarningShown=true;const ar=state.lang==='ar';openModal(`<div class="mobile-warning-modal"><div class="modal-head"><div><div class="eyebrow">${ar?'تنبيه قبل بدء الامتحان':'Important exam notice'}</div><h2>${ar?'هذا الامتحان غير مناسب للهاتف':'This exam is not designed for mobile'}</h2></div></div><div class="mobile-warning-body"><div class="warning-icon">!</div><p>${ar?'هذا الامتحان مصمم للعمل على الكمبيوتر أو اللابتوب. يفضل عدم استخدام الهاتف لأن بعض الأسئلة أو الملفات قد لا تظهر أو تعمل بالشكل المطلوب.':'This exam is designed for a desktop or laptop. Using a phone may cause some questions or files to display or work incorrectly.'}</p><div class="actions"><button type="button" class="btn ghost" onclick="closeModal()">${ar?'فهمت، المتابعة':'I understand, continue'}</button></div></div></div>`)}
function startTimer(){
  clearInterval(state.timer);
  if(!state.exam||!state.startedAt){
    console.error('Timer data missing',state.exam,state.startedAt);
    return;
  }
  const raw=String(state.startedAt);
  const normalized=raw.includes('T')?raw:raw.replace(' ','T');
  const parsed=Date.parse(normalized.endsWith('Z')?normalized:`${normalized}Z`);
  const duration=Number(state.exam.duration_minutes);
  if(!Number.isFinite(parsed)||!Number.isFinite(duration)||duration<=0){
    console.error('Invalid timer values:',state.startedAt,state.exam.duration_minutes);
    const el=document.getElementById('timer');
    if(el)el.textContent='--:--';
    return;
  }
  const end=parsed+(duration*60000);
  const tick=()=>{
    if(state.view!=='exam'){
      clearInterval(state.timer);
      return;
    }
    const left=Math.max(0,end-Date.now());
    const minutes=Math.floor(left/60000);
    const seconds=Math.floor(left/1000)%60;
    const el=document.getElementById('timer');
    if(el)el.textContent=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
    if(left<=0&&!state.submitting){
      clearInterval(state.timer);
      state.expired=true;
      submitExam(null,true);
    }
  };
  tick();
  state.timer=setInterval(tick,1000);
}
async function submitExam(e,expired=false){
  if(e)e.preventDefault();
  if(state.submitting)return;
  if(!state.attemptId){showToast('Exam attempt is missing');return;}
  const ar=state.lang==='ar';
  const answered=Object.keys(state.answers).length;
  if(!expired&&answered<state.questions.length){showToast(state.lang==='ar'?`لا يمكن التسليم. ${state.questions.length-answered} سؤال بدون إجابة.`:`Cannot submit. ${state.questions.length-answered} question(s) are unanswered.`);return;}
  if(!expired){
    const message=answered<state.questions.length
      ?(ar?`أجبت عن ${answered} من ${state.questions.length} سؤال. هل تريد تسليم الامتحان الآن؟`:`You answered ${answered} of ${state.questions.length} questions. Submit now?`)
      :(ar?'هل أنت متأكد من تسليم الامتحان؟':'Are you sure you want to submit the exam?');
    if(!confirm(message))return;
  }
  state.submitting=true;clearInterval(state.timer);
  const btn=document.getElementById('submit-exam-btn');
  if(btn){btn.disabled=true;btn.textContent=ar?'جارٍ التسليم…':'Submitting…'}
  const answers=Object.entries(state.answers).map(([questionId,answer])=>({questionId:Number(questionId),answer}));
  try{
    const d=await api(`/api/attempts/${state.attemptId}/submit`,{method:'POST',body:JSON.stringify({answers})});
    if(!d?.result)throw new Error('The exam was submitted but no result was returned');
    state.lastResult=d.result;state.view='result';renderResult(d.result);
  }catch(x){
    console.error('SUBMIT EXAM ERROR:',x);state.submitting=false;
    showToast(x.message||'Unable to submit the exam');
    if(btn){btn.disabled=false;btn.textContent=ar?'تسليم الامتحان ↗':'Submit exam ↗'}
    startTimer();
  }
}
function renderResult(r){
  const pct=Math.max(0,Math.min(100,Number(r.percentage)||0));
  const ar=state.lang==='ar';
  const passed=!!r.passed;
  const statusText=passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed');
  const message=passed?(ar?'لقد اجتزت هذا الامتحان بنجاح.':'You passed this assessment.'):(ar?'لم تصل إلى درجة النجاح هذه المرة. استمر في التدريب وحاول مرة أخرى.':'You did not reach the passing mark this time. Keep practicing and try again.');
  app.innerHTML=layout(`<main class="page result-page"><div class="result-shell">
    <div class="result-header"><div><div class="eyebrow">${ar?'اكتمل الامتحان':'Assessment complete'}</div><h1>${esc(r.examTitle)}</h1><p class="muted">${ar?'النتيجة النهائية':'Overall score'} · ${fmtDate(r.submittedAt||new Date().toISOString())}</p></div><span class="result-status ${passed?'is-pass':'is-fail'}"><span class="status-dot"></span>${statusText}</span></div>
    <section class="result-hero card">
      <div class="score-ring" style="--score:${pct}%"><div class="score-ring-inner"><strong>${pct.toFixed(1)}%</strong><span>${ar?'النتيجة':'Score'}</span></div></div>
      <div class="result-summary"><div class="eyebrow">${ar?'أداءك':'Your performance'}</div><h2>${message}</h2><p class="muted">${ar?'هذه النتيجة محسوبة تلقائياً بناءً على إجاباتك ودرجة النجاح المحددة للامتحان.':'This result was calculated automatically from your answers and the exam passing requirement.'}</p></div>
    </section>
    <section class="result-metrics">
      <div class="result-metric card"><span>${ar?'النقاط المحصلة':'Points earned'}</span><strong>${r.score} <small>/ ${r.totalPoints}</small></strong></div>
      <div class="result-metric card"><span>${ar?'درجة النجاح':'Pass mark'}</span><strong>${Number(r.passingPercentage??0).toFixed(0)}%</strong></div>
      <div class="result-metric card"><span>${ar?'الأسئلة المُجاب عنها':'Questions answered'}</span><strong>${r.answeredCount??'—'} <small>/ ${r.questionCount??'—'}</small></strong></div>
    </section>
    <div class="result-actions">${!passed&&r.examId?`<button class="btn orange" onclick="startExam(${Number(r.examId)})">${ar?'إعادة الامتحان':'Retake Exam'} ↗</button>`:''}<button class="btn ghost" onclick="go('dashboard')">${ar?'العودة إلى لوحة التحكم':'Back to Dashboard'} ↗</button></div>
  </div></main>`);
  if(state.lang==='ar')translateUI();
}
async function renderAdmin(){app.innerHTML=layout(`<div class="admin-layout"><aside class="sidebar"><button class="side-btn ${state.adminTab==='overview'?'active':''}" onclick="adminTab('overview')">Overview</button><button class="side-btn ${state.adminTab==='students'?'active':''}" onclick="adminTab('students')">Students</button><button class="side-btn ${state.adminTab==='exams'?'active':''}" onclick="adminTab('exams')">Exams</button><button class="side-btn ${state.adminTab==='results'?'active':''}" onclick="adminTab('results')">Results</button>${state.me.admin.role==='super_admin'?`<button class="side-btn ${state.adminTab==='admins'?'active':''}" onclick="adminTab('admins')">Admin Users</button>`:''}</aside><main class="admin-main" id="admin-main"></main></div>`);await loadAdminTab()}
function adminTab(t){state.adminTab=t;renderAdmin()}
async function loadAdminTab(){const el=document.getElementById('admin-main');if(state.adminTab==='overview')return adminOverview(el);if(state.adminTab==='students')return adminStudents(el);if(state.adminTab==='exams')return adminExams(el);if(state.adminTab==='results')return adminResults(el);if(state.adminTab==='admins')return adminAdmins(el)}
async function adminOverview(el){const d=await api('/api/admin/stats');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Control center</div><h1>Overview</h1><p class="muted">Manage the assessment platform.</p></div></div><div class="kpis"><div class="card kpi"><div class="muted">Students</div><div class="num">${d.students}</div></div><div class="card kpi"><div class="muted">Exams</div><div class="num">${d.exams}</div></div><div class="card kpi"><div class="muted">Attempts</div><div class="num">${d.attempts}</div></div><div class="card kpi"><div class="muted">Avg. score</div><div class="num">${d.averagePercentage.toFixed(1)}%</div></div></div><div class="grid grid-2 admin-section"><div class="card"><div class="eyebrow">Pass rate</div><div class="score" style="font-size:48px">${d.passRate.toFixed(1)}%</div><p class="muted">Across completed attempts.</p></div><div class="card"><h3>Admin</h3><p class="muted">Signed in as <b>${esc(state.me.admin.username)}</b> · ${esc(state.me.admin.role)}</p><button class="btn ghost" onclick="adminTab('exams')">Manage exams →</button></div></div>`}
async function adminStudents(el){const rows=await api('/api/admin/students');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">People</div><h1>Students</h1></div><div class="toolbar"><input id="studentSearch" placeholder="Search students…" oninput="searchStudents()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody id="students-body">${studentRows(rows)}</tbody></table></div></div>`}
function studentRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b></td><td>${esc(r.full_name)}</td><td>${esc(r.email)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="studentDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">No students found.</td></tr>`}
let searchTimer;async function searchStudents(){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=document.getElementById('studentSearch').value;const rows=await api('/api/admin/students?q='+encodeURIComponent(q));document.getElementById('students-body').innerHTML=studentRows(rows)},250)}
async function studentDetail(id){const d=await api(`/api/admin/students/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Student profile</div><h2>${esc(d.student.full_name)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-2"><div class="card"><b>Student ID</b><div style="font-size:24px;margin-top:8px">${esc(d.student.student_id)}</div><p>${esc(d.student.email)}</p><span class="pill">${d.student.status}</span><div class="actions" style="margin-top:15px"><button class="btn small ${d.student.status==='active'?'danger':'orange'}" onclick="toggleStudent(${id},'${d.student.status==='active'?'blocked':'active'}')">${d.student.status==='active'?'Block':'Activate'}</button></div></div><div class="card"><b>Exam results</b>${d.results.length?`<div class="stack" style="margin-top:12px">${d.results.map(r=>`<div class="statline"><span>${esc(r.title)}</span><span>${Number(r.percentage).toFixed(1)}%</span></div>`).join('')}</div>`:`<p class="muted">No results yet.</p>`}</div></div>`)}
async function toggleStudent(id,status){await api(`/api/admin/students/${id}`,{method:'PATCH',body:JSON.stringify({status})});closeModal();showToast('Student status updated');adminTab('students')}
async function adminExams(el){const rows=await api('/api/admin/exams');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Assessment design</div><h1>Exams</h1></div><button class="btn orange" onclick="examForm()">+ New Exam</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Exam</th><th>Questions</th><th>Duration</th><th>Pass</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b><div class="small-text muted">${esc(r.description||'')}</div></td><td>${r.question_count}</td><td>${r.duration_minutes} min</td><td>${r.passing_percentage}%</td><td><span class="pill">${r.status}</span></td><td><div class="actions"><button class="btn small ghost" onclick="questionManager(${r.id},'${esc(r.title).replaceAll("'","&#39;")}')">Questions</button><button class="btn small ghost" onclick='examForm(${JSON.stringify(r).replace(/'/g,"&#39;")})'>Edit</button><button class="btn small danger" onclick="deleteExam(${r.id})">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="6" class="empty">No exams.</td></tr>`}</tbody></table></div></div>`}
function attachmentRows(exam){let raw=exam?.attachments||exam?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(attachmentRow).join('')}
function attachmentRow(a={}){return `<div class="attachment-row"><div class="field"><label>File name</label><input name="attachmentName" maxlength="200" placeholder="e.g. Excel template" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="attachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.attachment-row').remove()">Remove</button></div>`}
function addAttachmentRow(){document.getElementById('attachmentRows')?.insertAdjacentHTML('beforeend',attachmentRow())}
function examForm(exam=null){openModal(`<div class="modal-head"><div><div class="eyebrow">${exam?'Edit exam':'Create exam'}</div><h2>${exam?'Update assessment':'New assessment'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveExam(event,${exam?.id||0})"><div class="field"><label>Title</label><input name="title" required value="${esc(exam?.title||'')}"></div><div class="field"><label>Description</label><textarea name="description" rows="3">${esc(exam?.description||'')}</textarea></div><div class="two-col"><div class="field"><label>Duration (minutes)</label><input name="durationMinutes" type="number" min="1" max="600" required value="${exam?.duration_minutes||30}"></div><div class="field"><label>Passing percentage</label><input name="passingPercentage" type="number" min="0" max="100" step="0.1" required value="${exam?.passing_percentage??50}"></div></div><div class="field"><label>Status</label><select name="status"><option value="active" ${exam?.status==='active'?'selected':''}>Active</option><option value="inactive" ${exam?.status!=='active'?'selected':''}>Inactive</option></select></div><label class="exam-mobile-setting"><input type="checkbox" name="mobileWarning" ${Number(exam?.mobile_warning||0)?'checked':''}><span><b>Show mobile warning</b><small>This exam is designed for desktop/laptop. Show a warning when a student opens it on a phone.</small></span></label><div class="card" style="padding:16px;background:var(--surface2)"><div class="eyebrow">Question resources</div><p class="small-text muted" style="margin:6px 0 0">Add files inside each question. A file will appear only with the question it belongs to.</p></div><button class="btn orange">Save Exam</button></form>`)}
async function saveExam(e,id){e.preventDefault();const fd=new FormData(e.target);const data={title:fd.get('title'),description:fd.get('description'),durationMinutes:fd.get('durationMinutes'),passingPercentage:fd.get('passingPercentage'),status:fd.get('status'),mobileWarning:fd.get('mobileWarning')==='on'};try{await api(id?`/api/admin/exams/${id}`:'/api/admin/exams',{method:id?'PUT':'POST',body:JSON.stringify(data)});closeModal();showToast('Exam saved');adminTab('exams')}catch(x){showToast(x.message)}}
async function deleteExam(id){if(!confirm('Delete this exam and all its questions/results?'))return;try{await api(`/api/admin/exams/${id}`,{method:'DELETE'});showToast('Exam deleted');adminTab('exams')}catch(x){showToast(x.message)}}
async function ensureXLSX(){
  if(window.XLSX)return window.XLSX;
  await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';sc.onload=resolve;sc.onerror=()=>reject(new Error('Could not load Excel importer'));document.head.appendChild(sc)});
  return window.XLSX;
}
function questionImportTemplate(){return [['Question','Option A','Option B','Option C','Option D','Correct Answer','Points','Sort Order','File Name','File URL'],['A company has fixed costs of $120,000 and a contribution margin per unit of $30. What is the break-even point in units?','3,000 units','4,000 units','5,000 units','6,000 units','C',1,1,'Case Study 1','https://example.com/case-study-1.pdf']];}
async function downloadQuestionTemplate(){try{const XLSX=await ensureXLSX();const ws=XLSX.utils.aoa_to_sheet(questionImportTemplate());const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Questions');XLSX.writeFile(wb,'exam-questions-template.xlsx')}catch(e){showToast(e.message)}}
async function exportQuestions(examId,title){try{const XLSX=await ensureXLSX();const qs=await api(`/api/admin/exams/${examId}/questions`);const rows=[['Question','Option A','Option B','Option C','Option D','Correct Answer','Points','Sort Order','File Name','File URL']];qs.forEach(q=>{const files=Array.isArray(q.attachments)&&q.attachments.length?q.attachments:[{name:'',url:''}];files.forEach((f,i)=>rows.push([q.question_text,q.option_a,q.option_b,q.option_c,q.option_d,q.correct_answer,q.points,q.sort_order||0,i? '':(f.name||''),i? '':(f.url||'')]))});const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=[{wch:55},{wch:28},{wch:28},{wch:28},{wch:28},{wch:16},{wch:10},{wch:12},{wch:28},{wch:60}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Questions');XLSX.writeFile(wb,`${String(title||'exam').replace(/[^a-z0-9_-]+/gi,'-')}-questions.xlsx`);showToast('Questions exported')}catch(e){showToast(e.message)}}
function openQuestionImport(examId,title){openModal(`<div class="modal-head"><div><div class="eyebrow">Bulk import</div><h2>Import questions</h2><p class="muted">Upload an Excel file to add many questions at once.</p></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><div class="card" style="padding:16px;background:var(--surface2);margin-bottom:16px"><b>Excel columns</b><p class="small-text muted" style="margin:8px 0 0">Question · Option A · Option B · Option C · Option D · Correct Answer · Points · Sort Order · File Name · File URL</p><button type="button" class="btn small ghost" style="margin-top:12px" onclick="downloadQuestionTemplate()">Download template</button></div><div class="field"><label>Excel file (.xlsx)</label><input id="questionImportFile" type="file" accept=".xlsx,.xls,.csv"></div><div id="questionImportPreview" class="small-text muted"></div><div class="actions" style="margin-top:16px"><button type="button" class="btn orange" onclick="runQuestionImport(${examId},'${esc(title).replaceAll("'","&#39;")}')">Import questions</button></div>`)}
async function runQuestionImport(examId,title){const input=document.getElementById('questionImportFile');if(!input?.files?.[0])return showToast('Choose an Excel file first');try{const XLSX=await ensureXLSX();const data=await input.files[0].arrayBuffer();const wb=XLSX.read(data,{type:'array'});const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:'',raw:false});if(!rows.length)throw new Error('No questions found in the file');const questions=rows.map((r,i)=>({questionText:r['Question']||r['question']||r['Question Text']||'',optionA:r['Option A']||r['A']||'',optionB:r['Option B']||r['B']||'',optionC:r['Option C']||r['C']||'',optionD:r['Option D']||r['D']||'',correctAnswer:String(r['Correct Answer']||r['Correct']||'').trim().toUpperCase(),points:Number(r['Points']||1),sortOrder:Number(r['Sort Order']||i+1),attachments:(r['File Name']||r['File URL'])?[{name:String(r['File Name']||'').trim(),url:String(r['File URL']||'').trim()}]:[]}));const bad=questions.filter(q=>!q.questionText||!q.optionA||!q.optionB||!q.optionC||!q.optionD||!['A','B','C','D'].includes(q.correctAnswer)||!Number.isFinite(q.points)||q.points<=0);if(bad.length)throw new Error(`${bad.length} question(s) need correction before import`);const res=await api('/api/admin/questions/bulk',{method:'POST',body:JSON.stringify({examId,questions})});closeModal();showToast(`Imported ${res.imported} questions`);await questionManager(examId,title)}catch(e){showToast(e.message)}}
