async function questionManager(examId,title){const qs=await api(`/api/admin/exams/${examId}/questions`);openModal(`<div class="modal-head"><div><div class="eyebrow">Question bank</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="actions" style="margin-bottom:15px"><button class="btn orange" onclick="questionForm(${examId},null,'${esc(title).replaceAll("'","&#39;")}')">+ Add Question</button><button class="btn ghost" onclick="openQuestionImport(${examId},'${esc(title).replaceAll("'","&#39;")}')">Import Excel</button><button class="btn ghost" onclick="exportQuestions(${examId},'${esc(title).replaceAll("'","&#39;")}')">Export Excel</button></div><div class="stack">${qs.map((q,i)=>{const files=Array.isArray(q.attachments)?q.attachments:[];return `<div class="card"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'} · Correct answer ${q.correct_answer}</div><b>${esc(q.question_text)}</b><p class="small-text muted">A. ${esc(q.option_a)} · B. ${esc(q.option_b)} · C. ${esc(q.option_c)} · D. ${esc(q.option_d)}</p>${files.length?`<div class="small-text"><b>Resources:</b> ${files.map(f=>esc(f.name)).join(' · ')}</div>`:''}<div class="actions"><button class="btn small ghost" onclick='questionForm(${examId},${JSON.stringify(q).replace(/'/g,"&#39;")},"${esc(title).replaceAll('"','&quot;')}")'>Edit</button><button class="btn small danger" onclick="deleteQuestion(${q.id},${examId},'${esc(title).replaceAll("'","&#39;")}')">Delete</button></div></div>`}).join('')||`<div class="empty">No questions yet.</div>`}</div>`)}
function questionAttachmentRows(q){let raw=q?.attachments||q?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(questionAttachmentRow).join('')}
function questionAttachmentRow(a={}){return `<div class="attachment-row question-attachment-row"><div class="field"><label>File name</label><input name="questionAttachmentName" maxlength="200" placeholder="e.g. Case study 1" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="questionAttachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.question-attachment-row').remove()">Remove</button></div>`}
function addQuestionAttachmentRow(){document.getElementById('questionAttachmentRows')?.insertAdjacentHTML('beforeend',questionAttachmentRow())}
function questionForm(examId,q,title){openModal(`<div class="modal-head"><div><div class="eyebrow">${q?'Edit question':'Add question'}</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="questionManager(${examId},'${esc(title).replaceAll("'","&#39;")}')">×</button></div><form class="form" onsubmit="saveQuestion(event,${examId},${q?.id||0},'${esc(title).replaceAll("'","&#39;")}')"><div class="field"><label>Question</label><textarea name="questionText" rows="4" required>${esc(q?.question_text||'')}</textarea></div><div class="two-col"><div class="field"><label>Option A</label><input name="optionA" required value="${esc(q?.option_a||'')}"></div><div class="field"><label>Option B</label><input name="optionB" required value="${esc(q?.option_b||'')}"></div><div class="field"><label>Option C</label><input name="optionC" required value="${esc(q?.option_c||'')}"></div><div class="field"><label>Option D</label><input name="optionD" required value="${esc(q?.option_d||'')}"></div></div><div class="two-col"><div class="field"><label>Correct answer</label><select name="correctAnswer">${['A','B','C','D'].map(x=>`<option ${q?.correct_answer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Points</label><input name="points" type="number" min="0.1" step="0.1" value="${q?.points||1}"></div></div><div class="field"><label>Sort order</label><input name="sortOrder" type="number" value="${q?.sort_order||0}"></div><div class="attachment-admin"><div class="section-head" style="margin:8px 0 12px"><div><div class="eyebrow">Question resources</div><h3 style="margin:4px 0 0">Files for this question</h3></div><button type="button" class="btn small ghost" onclick="addQuestionAttachmentRow()">+ Add file</button></div><p class="small-text muted">These files will appear only with this specific question during the exam.</p><div id="questionAttachmentRows" class="attachment-rows">${questionAttachmentRows(q)}</div></div><button class="btn orange">Save Question</button></form>`)}
async function saveQuestion(e,examId,id,title){e.preventDefault();const fd=new FormData(e.target);const names=fd.getAll('questionAttachmentName'),urls=fd.getAll('questionAttachmentUrl');const data=Object.fromEntries(fd);data.examId=examId;data.attachments=names.map((name,i)=>({name:String(name||'').trim(),url:String(urls[i]||'').trim()})).filter(x=>x.name&&x.url);try{await api(id?`/api/admin/questions/${id}`:'/api/admin/questions',{method:id?'PUT':'POST',body:JSON.stringify(data)});await questionManager(examId,title);showToast('Question saved')}catch(x){showToast(x.message)}}
async function deleteQuestion(id,examId,title){if(!confirm('Delete this question?'))return;await api(`/api/admin/questions/${id}`,{method:'DELETE'});await questionManager(examId,title);showToast('Question deleted')}

async function adminResults(el){const rows=await api('/api/admin/results');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Performance</div><h1>Results</h1></div><div class="toolbar"><input id="resultSearch" placeholder="Search results…" oninput="searchResults()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="results-body">${resultRows(rows)}</tbody></table></div></div>`}
function resultRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b><div class="small-text muted">${esc(r.full_name)}</div></td><td>${esc(r.title)}</td><td>${r.score}/${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="resultDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No results.</td></tr>`}
let resultTimer;async function searchResults(){clearTimeout(resultTimer);resultTimer=setTimeout(async()=>{const q=document.getElementById('resultSearch').value;const rows=await api('/api/admin/results?q='+encodeURIComponent(q));document.getElementById('results-body').innerHTML=resultRows(rows)},250)}
async function resultDetail(id){const d=await api(`/api/admin/results/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Result detail</div><h2>${esc(d.result.title)}</h2><p class="muted">${esc(d.result.student_id)} · ${esc(d.result.full_name)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-3"><div class="card"><b>Score</b><div class="score" style="font-size:35px">${Number(d.result.percentage).toFixed(1)}%</div></div><div class="card"><b>Points</b><p>${d.result.score} / ${d.result.total_points}</p></div><div class="card"><b>Status</b><p class="${d.result.passed?'success-text':'danger-text'}">${d.result.passed?'Passed':'Not passed'}</p></div></div><div class="stack" style="margin-top:16px">${d.answers.map((a,i)=>`<div class="card"><b>${i+1}. ${esc(a.question_text)}</b><p class="small-text">Selected: ${a.selected_answer||'No answer'} · Correct: ${a.correct_answer} · ${a.is_correct?'Correct':'Incorrect'}</p></div>`).join('')}</div>`)}
async function adminAdmins(el){const rows=await api('/api/admin/admins');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Access control</div><h1>Admin users</h1></div><button class="btn orange" onclick="adminForm()">+ Add Admin</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.username)}</b></td><td>${esc(r.role)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.id!==undefined?`<button class="btn small ghost" onclick="toggleAdmin(${r.id},'${r.status==='active'?'blocked':'active'}')">${r.status==='active'?'Block':'Activate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function adminForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Access control</div><h2>Add admin</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveAdmin(event)"><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._-]{3,80}" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role"><option value="admin">Admin</option><option value="super_admin">Super admin</option></select></div><button class="btn orange">Create Admin</button></form>`)}
async function saveAdmin(e){e.preventDefault();try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Admin created');adminTab('admins')}catch(x){showToast(x.message)}}
async function toggleAdmin(id,status){await api(`/api/admin/admins/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Admin status updated');adminTab('admins')}
function openModal(html){const d=document.createElement('div');d.id='modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en';localStorage.setItem('exam_lang',state.lang);document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';render()}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('exam_theme',state.theme);applyTheme();render()}
function applyTheme(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'}
function go(v){if(v==='admin-login'){location.href='/admin';return}if(v==='home'){if(location.pathname!=='/admin.html'&&location.pathname!=='/admin')state.view='home';else state.adminTab='overview'}else if(v==='results'){state.view=state.me?.user?'dashboard':'login'}else if(v==='dashboard'&&!state.me?.user){state.view='login'}else state.view=v;if(v!=='exam')clearInterval(state.timer);render()}
window.go=go;window.toggleLang=toggleLang;window.toggleTheme=toggleTheme;window.adminLogin=adminLogin;window.studentLogin=studentLogin;window.studentRegister=studentRegister;window.logout=logout;window.startExam=startExam;window.submitExam=submitExam;window.adminTab=adminTab;window.searchStudents=searchStudents;window.studentDetail=studentDetail;window.toggleStudent=toggleStudent;window.examForm=examForm;window.addAttachmentRow=addAttachmentRow;window.addQuestionAttachmentRow=addQuestionAttachmentRow;window.saveExam=saveExam;window.deleteExam=deleteExam;window.questionManager=questionManager;window.openQuestionImport=openQuestionImport;window.runQuestionImport=runQuestionImport;window.downloadQuestionTemplate=downloadQuestionTemplate;window.exportQuestions=exportQuestions;window.questionForm=questionForm;window.saveQuestion=saveQuestion;window.deleteQuestion=deleteQuestion;window.searchResults=searchResults;window.resultDetail=resultDetail;window.adminForm=adminForm;window.saveAdmin=saveAdmin;window.toggleAdmin=toggleAdmin;window.closeModal=closeModal;
boot();
